import{_ as a,o as t,c as r,a0 as i}from"./chunks/framework.BQGW-Zpy.js";const p=JSON.parse('{"title":"UZH Blockchain","description":"","frontmatter":{},"headers":[],"relativePath":"project/uzh-blockchain.md","filePath":"project/uzh-blockchain.md"}'),o={name:"project/uzh-blockchain.md"};function n(l,e,c,d,s,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="uzh-blockchain" tabindex="-1">UZH Blockchain <a class="header-anchor" href="#uzh-blockchain" aria-label="Permalink to &quot;UZH Blockchain&quot;">​</a></h1><p>F2F Cross-Border started here as a project for the University of Zurich&#39;s <strong>Deep Dive into Blockchain (DDiB 2026)</strong> summer school, before the later extension for ETHGlobal Lisbon 2026 (covered separately in <a href="./ethglobal-lisbon.html">ETHGlobal Lisbon 2026</a>).</p><h2 id="the-core-idea" tabindex="-1">The core idea <a class="header-anchor" href="#the-core-idea" aria-label="Permalink to &quot;The core idea&quot;">​</a></h2><p>Correspondent banking routes a cross-border payment through a chain of intermediary banks, each one adding delay and hiding its cut in the FX spread, and the newer crypto ramps that promise to fix this still hand the sender a wallet. The idea researched and built here takes a third path: licensed partners handle the fiat on-ramp and off-ramp exactly as they do today, a compliant stablecoin carries the value across the border, and Hedera&#39;s public consensus network makes every compliance and routing decision independently verifiable, without either side of the transfer ever touching a wallet.</p><h2 id="what-was-actually-implemented-phase-by-phase" tabindex="-1">What was actually implemented, phase by phase <a class="header-anchor" href="#what-was-actually-implemented-phase-by-phase" aria-label="Permalink to &quot;What was actually implemented, phase by phase&quot;">​</a></h2><h3 id="foundation-17–18-july-the-hedera-trust-layer-and-the-base-app" tabindex="-1">Foundation (17–18 July): the Hedera trust layer and the base app <a class="header-anchor" href="#foundation-17–18-july-the-hedera-trust-layer-and-the-base-app" aria-label="Permalink to &quot;Foundation (17–18 July): the Hedera trust layer and the base app&quot;">​</a></h3><ul><li>Real Hedera Consensus Service (HCS) anchoring, Mirror Node verification, and a working tamper-detection proof, the mechanism the entire project&#39;s credibility rests on, built and verified first, before any UI.</li><li>A GitBook-ready documentation site, expanded to a full 32-page project document.</li><li>Frontend and backend integrated into one working application, with a real <code>/api/health</code> endpoint and a settlement fallback chain (Ethereum, Solana, Base).</li></ul><h3 id="_19-july-real-corridors-real-partners-real-docs" tabindex="-1">19 July: real corridors, real partners, real docs <a class="header-anchor" href="#_19-july-real-corridors-real-partners-real-docs" aria-label="Permalink to &quot;19 July: real corridors, real partners, real docs&quot;">​</a></h3><ul><li>Per-corridor settlement speed figures, a light theme, real brand assets, and a working demo mode.</li><li>Actual partner research for the Portugal-Armenia corridor, plus MTN and Airtel research for African mobile-money corridors.</li><li>A stablecoin liquidity market-share table and chart across five settlement chains, and a full security &amp; privacy document covering selective disclosure.</li><li>A critical fix: a 500 error on payment submission caused by missing required anchor fields.</li></ul><h3 id="_20-july-real-content-a-dedicated-landing-page-terminology-accuracy" tabindex="-1">20 July: real content, a dedicated landing page, terminology accuracy <a class="header-anchor" href="#_20-july-real-content-a-dedicated-landing-page-terminology-accuracy" aria-label="Permalink to &quot;20 July: real content, a dedicated landing page, terminology accuracy&quot;">​</a></h3><ul><li>A custom icon set, a dedicated landing page, and fact-checked problem/solution/target-market content backed by sourced data.</li><li>A project-wide terminology sweep correcting inaccurate language like &quot;Hedera Blockchain&quot; to &quot;Hedera network&quot;, since Hedera is a hashgraph-based public network, not a blockchain.</li><li>Go-to-market, alternative-approaches, and token-decision strategy documents.</li></ul><h3 id="_21-july-the-mobile-app-shell-community-feature-and-real-testing" tabindex="-1">21 July: the mobile app shell, community feature, and real testing <a class="header-anchor" href="#_21-july-the-mobile-app-shell-community-feature-and-real-testing" aria-label="Permalink to &quot;21 July: the mobile app shell, community feature, and real testing&quot;">​</a></h3><ul><li>A distinct mobile app shell, wired to the same real backend as the web version, not a separate simulation.</li><li>The Community feature (web and app), gated by a real Community Usage Code issued only after a genuine Hedera anchor.</li><li>LatAm partner research (EBANX, Mercado Pago, PayU) and TAM/SAM/SOM market sizing.</li><li>A critical fix: the verify endpoint was never actually checking Hedera, it was returning fabricated demo anchor data.</li><li>Real Vitest + Supertest and Playwright end-to-end tests added, closing the gap between what the project report claimed and what actually ran.</li><li>The 5-year global-capture revenue projection model.</li></ul><h3 id="_22-july-a-real-database-a-full-accuracy-sweep-and-the-pitch-groundwork" tabindex="-1">22 July: a real database, a full accuracy sweep, and the pitch groundwork <a class="header-anchor" href="#_22-july-a-real-database-a-full-accuracy-sweep-and-the-pitch-groundwork" aria-label="Permalink to &quot;22 July: a real database, a full accuracy sweep, and the pitch groundwork&quot;">​</a></h3><ul><li>Migration to a real MongoDB + Prisma database, closing the last gap between the report and the running system.</li><li>A full documentation accuracy pass: removing every instance of hedging language and unnecessary em-dashes across the whole docs site, and a content-accuracy pass correcting a testing doc that had described an unbuilt Stripe webhook test as if it were real.</li><li>Site Tour and App Tour pages, with a screenshot of every page and screen.</li><li>A critical fix to the compliance verification flow: two different compliance records were being hashed and compared against each other, which is why verification kept failing on real transactions.</li></ul><h3 id="_23-july-the-pitch-video" tabindex="-1">23 July: the pitch video <a class="header-anchor" href="#_23-july-the-pitch-video" aria-label="Permalink to &quot;23 July: the pitch video&quot;">​</a></h3><ul><li><code>pitch-video.html</code>, a standalone animated pitch presentation, embedded on the Home page under the hero section.</li></ul><h2 id="where-this-hands-off" tabindex="-1">Where this hands off <a class="header-anchor" href="#where-this-hands-off" aria-label="Permalink to &quot;Where this hands off&quot;">​</a></h2><p>Everything above was the complete, working UZH submission by the 23 July hand-in. The Hedera Schedule Service completion anchor, the 2-of-2 threshold-key intermediary account, the dedicated completion topic, the How It Works walkthrough, and the SaucerSwap liquidity source were all added afterward, specifically for the ETHGlobal Lisbon 2026 extension, see <a href="./ethglobal-lisbon.html">ETHGlobal Lisbon 2026</a> for that phase.</p>',19)])])}const m=a(o,[["render",n]]);export{p as __pageData,m as default};
